#include <iostream>

class Dato {
public:
    explicit Dato(int numero) : numero_{numero} {}
    int numero() const { return numero_; }
    void poner(int numero) { numero_ = numero; }
private:
    int numero_;
};
int numero_de(const Dato& dato) {
    return dato.numero();
}
void cambiar_dato(Dato& dato, int nuevo) {
    dato.poner(nuevo);
}
class LecturaConAyuda : private Dato {
public:
    explicit LecturaConAyuda(int numero) : Dato{numero} {}
    int valor() const { return numero_de(*this); }
    void cargar(int numero) { cambiar_dato(*this, numero); }
    int desde_puntero() const {
        const Dato* vista = this;
        return vista->numero();
    }
};
int main() {
    LecturaConAyuda dato{8};
    std::cout << dato.valor() << ':' << dato.desde_puntero() << '|';
    dato.cargar(3);
    std::cout << dato.valor();
    return 0;
}

